// 24時間以内のRSS記事のみ抽出し、正規化する
const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
const sourceRow = $item(0).$node['Split RSS Sources (Loop)']?.json || {};
const allInputs = $input.all();
const filteredItems = [];

// RSS Feed Readの出力を処理
for (const inputItem of allInputs) {
  const rssData = inputItem.json;

  // RSS記事の配列を取得（複数の可能性のあるフィールド名に対応）
  const articles = rssData.items || rssData.entries || (Array.isArray(rssData) ? rssData : [rssData]);

  if (articles && Array.isArray(articles)) {
    for (const article of articles) {
      // 日付パース（複数の可能性のある日付フィールドに対応）
      const dateStr = article.pubDate || article.isoDate || article.published || article.date;
      if (!dateStr) continue;

      const pubDate = new Date(dateStr);
      if (isNaN(pubDate.getTime())) continue; // 無効な日付をスキップ

      // 24時間以内の記事のみ処理
      if (pubDate > oneDayAgo) {
        filteredItems.push({
          title: article.title || 'タイトル不明',
          link: article.link || article.url || '',
          pubDate: pubDate.toISOString(),
          summary: article.contentSnippet || article.summary || article.content || '',
          sourceRow: sourceRow,
          rssSource: sourceRow.B || '不明なソース',
          category: sourceRow.A || 'その他'
        });
      }
    }
  }
}

console.log(`RSS処理完了: ${filteredItems.length}件の24時間以内記事を抽出`);
return filteredItems.map(item => ({ json: item }));

// 検索結果をRSSと同じフォーマットに整形して返す
const out = [];
const body = $input.item.json;
if (body.articles) {
  for (const a of body.articles) {
    out.push({ title: a.title, link: a.url || a.link, pubDate: a.publishedAt || a.pubDate, summary: a.description || a.content });
  }
} else if (body.items) {
  for (const a of body.items) {
    out.push({ title: a.title, link: a.link, pubDate: a.pagemap && a.pagemap.metatags ? a.pagemap.metatags[0]['article:published_time'] : null, summary: a.snippet || '' });
  }
}
return out.map(i => ({ json: i }));

// プロンプト設定をカテゴリ別に整理し、有効なプロンプトのみ抽出
const prompts = {};
const items = $input.all();

for (const item of items) {
  const row = item.json;
  // ヘッダー行をスキップ
  if (row.A === 'プロンプトID' || !row.A) continue;

  // 有効なプロンプトのみ処理
  if (row.E === '有効' || row.E === 'TRUE') {
    const category = row.B || 'default';
    const promptType = row.C || 'filter';

    if (!prompts[category]) {
      prompts[category] = {};
    }

    prompts[category][promptType] = {
      id: row.A,
      content: row.D || '',
      version: row.F || '1.0',
      notes: row.G || ''
    };
  }
}

// 全カテゴリのプロンプト設定を1つのオブジェクトとして返す
return [{ json: { promptSettings: prompts } }];

// RSS結果と検索結果を統合し、URL基準で重複排除
const allItems = $input.all();
const articles = [];

// 各入力からデータを抽出
for (const item of allItems) {
  if (item.json) {
    if (Array.isArray(item.json)) {
      // 配列の場合は展開
      articles.push(...item.json);
    } else if (item.json.title && item.json.link) {
      // 記事オブジェクトの場合は直接追加
      articles.push(item.json);
    }
  }
}

// URL基準で重複排除（nullやundefinedのlinkは除外）
const validArticles = articles.filter(a => a.link && a.link.trim());
const uniqueArticles = validArticles.filter((article, index, self) => 
  index === self.findIndex(a => a.link === article.link)
);

// カテゴリ別に自動分類
const categorized = {
  'AI最新情報': [],
  'AI活用事例': [],
  'N8N事例': []
};

for (const article of uniqueArticles) {
  const title = (article.title || '').toLowerCase();
  const summary = (article.summary || '').toLowerCase();
  const content = title + ' ' + summary;

  // カテゴリ分類ロジック
  if (/ai|openai|gpt|claude|llm|機械学習|深層学習|neural/i.test(content)) {
    if (/導入|事例|活用|roi|成功|効果|実践|事例研究/i.test(content)) {
      categorized['AI活用事例'].push(article);
    } else {
      categorized['AI最新情報'].push(article);
    }
  } else if (/n8n|ワークフロー|自動化|automation|workflow/i.test(content)) {
    categorized['N8N事例'].push(article);
  } else {
    // デフォルトはAI最新情報
    categorized['AI最新情報'].push(article);
  }
}

// カテゴリタグ付きで出力配列を構築
const output = [];
for (const [category, articles] of Object.entries(categorized)) {
  for (const article of articles) {
    output.push({
      category: category,
      title: article.title || '',
      link: article.link || '',
      pubDate: article.pubDate || new Date().toISOString(),
      summary: article.summary || '',
      sourceCategory: article.sourceRow?.A || '',
      originalData: article
    });
  }
}

console.log(`統合完了: ${uniqueArticles.length}記事を処理, ${output.length}記事を出力`);
return output.map(item => ({ json: item }));

