// OpenAIフィルタリング結果を解析し、通過した記事のデータを次のノードに渡す
const filterResponse = $input.item.json;
let keep = false;
let reason = '';

// OpenAIフィルタリング結果を解析
if (filterResponse && filterResponse.choices && filterResponse.choices[0]) {
  try {
    const responseText = filterResponse.choices[0].message.content.trim();
    const parsed = JSON.parse(responseText);
    keep = parsed.keep === 'yes' || parsed.keep === true;
    reason = parsed.reason || 'AI判定通過';
  } catch (e) {
    console.log('フィルタ結果パースエラー:', e.message);
    console.log('レスポンステキスト:', filterResponse.choices[0].message.content);
    // パースエラーの場合は安全のため除外
    keep = false;
    reason = 'JSON解析エラー';
  }
}

// フィルタリングで除外された記事は処理終了
if (!keep) {
  console.log(`記事が除外されました: ${reason}`);
  return [];
}

// 元記事データを取得（Split In Batches から）
const batchNode = $node['Split In Batches - By Category'];
let articleData = {};

if (batchNode && batchNode.json) {
  articleData = batchNode.json;
} else {
  // フォールバック: 現在の実行コンテキストから取得を試行
  const currentExecution = $execution;
  if (currentExecution && currentExecution.data && currentExecution.data.main) {
    const batchData = currentExecution.data.main[0];
    if (batchData && batchData.length > 0) {
      articleData = batchData[0].json;
    }
  }
}

// 記事データにフィルタ結果を追加
const enrichedArticleData = {
  ...articleData,
  filter_reason: reason,
  filter_passed: true,
  filter_timestamp: new Date().toISOString()
};

console.log(`フィルタ通過: ${enrichedArticleData.title || '不明な記事'}`);
console.log(`理由: ${reason}`);

return [{ json: enrichedArticleData }];

