// 全ての生成結果を統合してシート書き込み用データを作成（N8N v1.0+ 対応）
// 画像プロンプト生成が最終ステップなので、ここで全てのデータを統合

const currentInput = $input.item.json; // 画像プロンプト生成結果
let imagePromptData = { image_prompt: '' };
let postData = { post: '', hashtags: [] };
let articleData = { category: 'AI最新情報', title: '', link: '', summary: '' };

// 1. 現在の入力（画像プロンプト生成結果）を解析
if (currentInput && currentInput.choices && currentInput.choices[0]) {
  try {
    const content = currentInput.choices[0].message.content.trim();
    imagePromptData = JSON.parse(content);
    console.log('✅ 画像プロンプト取得成功');
  } catch (e) {
    console.log('❌ 画像プロンプト解析エラー:', e.message);
    imagePromptData = { image_prompt: '画像生成用プロンプトの解析に失敗しました' };
  }
}

// 2. 実行履歴から過去のノード結果を検索
const execution = $execution;
if (execution && execution.data && execution.data.main && execution.data.main[0]) {
  const executionItems = execution.data.main[0];
  console.log(`実行履歴から ${executionItems.length} 件のアイテムを検索中...`);

  // 投稿文生成結果を検索（OpenAI レスポンス形式で post フィールドがあるもの）
  for (let i = executionItems.length - 1; i >= 0; i--) {
    const item = executionItems[i];
    if (item && item.json && item.json.choices && item.json.choices[0]) {
      try {
        const content = item.json.choices[0].message.content;
        const parsed = JSON.parse(content);
        if (parsed.post && !parsed.image_prompt) {
          postData = parsed;
          console.log('✅ 投稿文データ発見:', (parsed.post || '').slice(0, 30) + '...');
          break;
        }
      } catch (e) {
        // JSON解析失敗は正常（他のOpenAI呼び出しの可能性）
      }
    }
  }

  // 記事データを検索（title, link, category フィールドがあるもの）
  for (let i = executionItems.length - 1; i >= 0; i--) {
    const item = executionItems[i];
    if (item && item.json && item.json.title && item.json.link && item.json.category) {
      articleData = item.json;
      console.log('✅ 記事データ発見:', (articleData.title || '').slice(0, 30) + '...');
      break;
    }
  }
}

// 3. デフォルト値の設定
if (!postData.post) {
  postData.post = '投稿文の生成に失敗しました。手動で作成してください。';
  postData.hashtags = ['#AI', '#自動化'];
}

if (!articleData.title) {
  articleData = {
    category: 'AI最新情報',
    title: 'タイトルの取得に失敗しました',
    link: '',
    summary: 'データ取得エラー'
  };
}

// 4. シート4の行データを作成
const now = new Date();
const jstTime = new Date(now.getTime() + (9 * 60 * 60 * 1000)).toISOString().replace('T', ' ').slice(0, 19);

const row = [
  jstTime, // A: 日付（JST形式）
  articleData.category, // B: カテゴリ
  (articleData.title || '').slice(0, 200), // C: 元記事タイトル（200文字制限）
  articleData.link || '', // D: 元記事URL
  (postData.post || '').slice(0, 400), // E: 生成された投稿文（400文字制限）
  Array.isArray(postData.hashtags) ? postData.hashtags.join(' ') : (postData.hashtags || ''), // F: ハッシュタグ
  imagePromptData.image_prompt || '', // G: 推奨画像プロンプト
  '未投稿', // H: 投稿済みフラグ
  '', // I: 投稿先（手動入力用）
  `N8N自動生成 ${jstTime}` // J: 備考
];

// 5. 結果をログ出力
console.log('=== シート書き込みデータ生成完了 ===');
console.log('記事:', articleData.title || 'なし');
console.log('投稿文:', (postData.post || 'なし').slice(0, 50) + (postData.post && postData.post.length > 50 ? '...' : ''));
console.log('画像プロンプト:', (imagePromptData.image_prompt || 'なし').slice(0, 30) + (imagePromptData.image_prompt && imagePromptData.image_prompt.length > 30 ? '...' : ''));
console.log('書き込み行:', row.map(cell => (cell || '').toString().slice(0, 20)).join(' | '));

return [{ json: { values: [row] } }];

